data_contract.shared_types:
{ "id": int, "title": string, "last_message_at": iso8601|null, "created_at": iso8601, "messages": AiMessage[]?, "active_turn": AiTurn|null? }
"queued"|"running"|"awaiting_confirmation"|"completed"|"failed"|"cancelled"|"limit_reached"
{ "id": int, "conversation_id": int, "status": AiTurnStatus, "user_message_id": int, "assistant_text": string, "assistant_message": AiMessage|null, "steps": AiTurnStep[], "preview": AiPreview|null, "queue_position": int|null, "error_code": AiTurnErrorCode|null, "error_message": string|null, "created_at": iso8601, "updated_at": iso8601, "finished_at": iso8601|null }
{ "index": int, "tool": "search_operations"|"list_records"|"run_read_code"|"prepare_write", "label": string, "state": "running"|"done"|"failed" }
{ "id": string, "operation": string, "record": { "type": string, "id": int|string|null, "label": string|null }, "changes": [ { "field": string, "label": string, "before": mixed, "after": mixed } ], "effects": string[], "expires_at": iso8601, "state": "open"|"confirmed"|"cancelled"|"expired"|"rejected"|"uncertain"|"stale", "outcome": AiPreviewOutcome|null }
"succeeded"|"rejected"|"uncertain"|"expired"|"cancelled"|"stale"
"model_unavailable"|"connector_unavailable"|"link_lost"|"too_many_steps"|"turn_timeout"|"stream_error"| "switched_off"|"limit_person"|"limit_total"|"internal"

endpoint.errors:
401; 403 conversazione altrui; 404 anteprima non del turno ("Preview not found.");
409 anteprima non piu' aperta, `data.reason` = `expired` | `already_used` | `not_open`
("This preview is no longer open."); 422 forma di `preview_id`;
503 connettore non raggiungibile ("The assistant could not reach its tools. Try again later."): l'anteprima resta
`open` finche' non scade; esito incerto della conferma: nessuna ripetizione automatica, il turno riprende con
esito `uncertain` dopo la lettura di verifica del connettore.

endpoint.response:
{ "items": [ { "id": string, "name": string, "context_length": int,
          "pricing": { "prompt": string, "completion": string, "input_cache_read": string|null, "request": string|null },
          "selected": bool } ], "pagination": {...} }

internal_contract.item:
Memoria (D-5): soglia di riassunto in percentuale della finestra di contesto del modello (da OpenRouter);
      risultati degli strumenti per intero solo nel turno in corso; riassunto salvato sulla conversazione, costo nel
      registro; dopo `summary_count` pari a un massimo di configurazione l'assistente propone una conversazione nuova.
